(6047563, 887980, 61084, '<td valign="top">A cool photo, but DNMC. There is no church in the photo...just a cross.</td>', 'A cool photo, but DNMC. There is no church in the photo...just a cross.', '2010-06-09 01:21:37.000000', NULL, 1),
(6047568, 889554, 96751, '<td valign="top">Stunning.  Front page.</td>', 'Stunning.  Front page.', '2010-06-09 01:23:30.000000', NULL, 1),
(6047576, 889653, 96751, '<td valign="top">Very interesting perspective.</td>', 'Very interesting perspective.', '2010-06-09 01:25:48.000000', NULL, 1),
(6047580, 887786, 96751, '<td valign="top">Simply exquisite.  Unique pov, and spot on processing.  Front page.</td>', 'Simply exquisite.  Unique pov, and spot on processing.  Front page.', '2010-06-09 01:26:48.000000', NULL, 1),
(6047584, 889762, 96751, '<td valign="top">Stellar lighting, wonderful reflection.  Perfectly processed.  Front page.</td>', 'Stellar lighting, wonderful reflection.  Perfectly processed.  Front page.', '2010-06-09 01:27:21.000000', NULL, 1),
(6047628, 888932, 94241, '<td valign="top">I think the out-of-focus cross grabs the attention away from your subject.  I think this is mostly because it sticks out into a clear space while the subject is kind of lost in and amongst a bunch of other shapes and textures.</td>', 'I think the out-of-focus cross grabs the attention away from your subject.  I think this is mostly because it sticks out into a clear space while the subject is kind of lost in and amongst a bunch of other shapes and textures.', '2010-06-09 01:43:06.000000', NULL, 1),
(6047635, 889526, 94241, '<td valign="top">If I could suggest one tweak to this image, it''d be to crop to a wider aspect ratio.  I think the alien-ness of the image really needs a more theatrical, wider, image.</td>', 'If I could suggest one tweak to this image, it''d be to crop to a wider aspect ratio.  I think the alien-ness of the image really needs a more theatrical, wider, image.', '2010-06-09 01:46:27.000000', NULL, 1),
(6047649, 889654, 94241, '<td valign="top">If there was just a bit more sky I think the building crowns would stand out more.</td>', 'If there was just a bit more sky I think the building crowns would stand out more.', '2010-06-09 01:51:14.000000', NULL, 1),
(6047657, 887980, 30861, '<td valign="top">Mount Soledad, I believe... Many a photo I''ve taken from there, back in the day.</td>', 'Mount Soledad, I believe... Many a photo I''ve taken from there, back in the day.', '2010-06-09 01:53:30.000000', NULL, 1),
(6047658, 887863, 94241, '<td valign="top">The tree branches are a barrier between the viewer and the photo.  Being kind of blurry and halo-ey, they kind of dominate the photo.  This is a BEAUTIFUL shot, wonderful framing, lighting, texture, color, everything... except for the branches.</td>', 'The tree branches are a barrier between the viewer and the photo.  Being kind of blurry and halo-ey, they kind of dominate the photo.  This is a BEAUTIFUL shot, wonderful framing, lighting, texture, color, everything... except for the branches.', '2010-06-09 01:53:33.000000', NULL, 1),
