INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6049912, 889342, 35044, '<td valign="top">Lacking any kind of real impact, contrast too low in the framing arch, which looks muddy and noisy - the "modern news" bit is only determinable through a written sign, which is not good storytelling via photography. Not sure it shouts "church" too loudly.</td>', 'Lacking any kind of real impact, contrast too low in the framing arch, which looks muddy and noisy - the "modern news" bit is only determinable through a written sign, which is not good storytelling via photography. Not sure it shouts "church" too loudly.', '2010-06-10 11:52:58.000000', NULL, 1),
(6049913, 889674, 35044, '<td valign="top">The lean makes me feel queasy :-(<br/> <br/>Does not scream "church" to me.</td>', 'The lean makes me feel queasy :-( Does not scream "church" to me.', '2010-06-10 11:53:32.000000', NULL, 1),
(6049914, 889663, 35044, '<td valign="top">Your sharpening approach has played havoc with the church bricks - has become unattractive as a result.  Also light is not ideal - nice evening light, but not lighting the main area of the photo.</td>', 'Your sharpening approach has played havoc with the church bricks - has become unattractive as a result.  Also light is not ideal - nice evening light, but not lighting the main area of the photo.', '2010-06-10 11:54:56.000000', NULL, 1),
(6049915, 889500, 35044, '<td valign="top">Lighting is just feeling odd here  at this shooting anglem - both looking up - might look better more side on, if there were such a spot to shoot from.</td>', 'Lighting is just feeling odd here  at this shooting anglem - both looking up - might look better more side on, if there were such a spot to shoot from.', '2010-06-10 11:56:49.000000', NULL, 1),
(6049917, 889057, 35044, '<td valign="top">Sharpening is really odd here - the rooves either side of the church are both better lit and sharper than the main frontage.  Colours are also washed out.  I think that you''ve tried to rescue this image shot into the sun with a lot of fill light, and it has not quite worked.</td>', 'Sharpening is really odd here - the rooves either side of the church are both better lit and sharper than the main frontage.  Colours are also washed out.  I think that you''ve tried to rescue this image shot into the sun with a lot of fill light, and it has not quite worked.', '2010-06-10 11:58:10.000000', NULL, 1),
(6049918, 888285, 35044, '<td valign="top">Processing is just unattractive, I''m afraid.</td>', 'Processing is just unattractive, I''m afraid.', '2010-06-10 11:58:30.000000', NULL, 1),
(6049921, 888325, 35044, '<td valign="top">Sadly the title is not conveyed by the image...<br/> <br/>The subject statue is facing away from us (not v interesting).<br/> <br/>Image is not helped by not being straight and the composition has left the church in an odd position in the frame - not a focus point whereas the challenge is "churches".</td>', 'Sadly the title is not conveyed by the image... The subject statue is facing away from us (not v interesting). Image is not helped by not being straight and the composition has left the church in an odd position in the frame - not a focus point whereas the challenge is "churches".', '2010-06-10 12:01:03.000000', NULL, 1),
(6049924, 887994, 113419, '<td valign="top">I like your point of view but in my opinion you should have made just a slight adjustment of your postion so that you could have gotten in the very top (with some blue sky) of that section on the left.</td>', 'I like your point of view but in my opinion you should have made just a slight adjustment of your postion so that you could have gotten in the very top (with some blue sky) of that section on the left.', '2010-06-10 12:08:16.000000', NULL, 1),
(6049928, 889875, 113419, '<td valign="top">in my opinion this is a little too busy and more about the fountain than the church</td>', 'in my opinion this is a little too busy and more about the fountain than the church', '2010-06-10 12:09:49.000000', NULL, 1),
(6049957, 889478, 110792, '<td valign="top">Pattern is beautiful. I would have loved it more if the person wasn''t in motion. It kind of distracts my eyes too much from the great symmetry of the church.</td>', 'Pattern is beautiful. I would have loved it more if the person wasn''t in motion. It kind of distracts my eyes too much from the great symmetry of the church.', '2010-06-10 12:41:21.000000', NULL, 1),
