(6066489, 889679, 115814, '<td valign="top">I really liked this - gave it one of my highest scores, as it jumped out of the pack with an original take on the theme. Sorry it didn''t fare better.</td>', 'I really liked this - gave it one of my highest scores, as it jumped out of the pack with an original take on the theme. Sorry it didn''t fare better.', '2010-06-22 22:46:42.000000', NULL, 0),
(6082761, 889719, 75713, '<td valign="top">You must have a very good heart and an old soul.  It''s a beautiful photo and having the Mala beads in front of the Monk makes it even more powerful.</td>', 'You must have a very good heart and an old soul.  It''s a beautiful photo and having the Mala beads in front of the Monk makes it even more powerful.', '2010-07-06 22:09:41.000000', NULL, 0),
(6087119, 889867, 54645, '<td valign="top">Wow, this has a strong funk to it. I lot of personal interpretation to be had here, well done Brian.</td>', 'Wow, this has a strong funk to it. I lot of personal interpretation to be had here, well done Brian.', '2010-07-10 01:56:56.000000', NULL, 0),
(6087360, 889731, 23484, '<td valign="top">Very cool point of view.</td>', 'Very cool point of view.', '2010-07-10 12:35:31.000000', NULL, 0),
(6109762, 889441, 40718, '<td valign="top">Did I ever tell you I was born in Calgary?  Anyway, I have usually been starting way down in the 5.5s, but I''ll start with your highest scoring shot.  I think this shot is excellent as a landscape.  I saw in your notes that you used ND filters.  I have to say, I haven''t pulled mine out in ages because bracketing and manual blending of exposures in PS can do such a great job.  Either way, you did well with the sky, but I thought I''d offer the idea up for you to join the 21st century. ;)  The hearty, yellow tones contrast nicely with the sky.  I''d be proud to have this on my profile.</td>', 'Did I ever tell you I was born in Calgary?  Anyway, I have usually been starting way down in the 5.5s, but I''ll start with your highest scoring shot.  I think this shot is excellent as a landscape.  I saw in your notes that you used ND filters.  I have to say, I haven''t pulled mine out in ages because bracketing and manual blending of exposures in PS can do such a great job.  Either way, you did well with the sky, but I thought I''d offer the idea up for you to join the 21st century. ;)  The hearty, yellow tones contrast nicely with the sky.  I''d be proud to have this on my profile.', '2010-07-30 18:27:08.000000', NULL, 0),
(6119212, 889867, 50641, '<td valign="top">Wow, what a perspective. Makes you imagine the photographer is in a steaming pit. Love the grime. This merits a short story or poem, or at least a scene in the next Omen movie.</td>', 'Wow, what a perspective. Makes you imagine the photographer is in a steaming pit. Love the grime. This merits a short story or poem, or at least a scene in the next Omen movie.', '2010-08-05 10:58:59.000000', NULL, 0),
(6525080, 889478, 12611, '<td valign="top">Beautiful shot; the eyes go from blurred to focus on the gold, its awesome.</td>', 'Beautiful shot; the eyes go from blurred to focus on the gold, its awesome.', '2011-09-02 15:35:18.000000', NULL, 0);
